"""Build English report and standalone interactive ranking from saved analysis."""
import csv,hashlib,html,json,subprocess
from pathlib import Path
A=Path(__file__).resolve().parent

def read(n):return json.loads((A/n).read_text())
def pct(x):return 'N/A' if x is None else '%.2f%%'%(100*x)
def table(rows):
 return '\n'.join(['|Case|Pass / valid|Pass rate|Excluded / unverified groups|','|---|---:|---:|---:|']+['|`%s`|%d/%d|%s|%d|'%(r['case_id'],r['passes'],r['valid_scores'],pct(r['pass_rate']),r['excluded_or_unverified']) for r in rows])
def main():
 s=read('summary.json');rank=read('case-ranking.json');groups=read('execution-groups.json');raw=list(csv.DictReader((A/'case_ranking_raw_receipts.csv').open(encoding='utf-8-sig')))
 keep=[r for r in groups if r['model'] in s['models']]
 data=[{k:r[k] for k in ['case_id','model','effort','condition','variant','workflow_profile','timeout_seconds','valid_score','verdict','raw_copies']} for r in keep]
 payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 webpage='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Historical case pass-rate ranking</title><style>
body{font:15px system-ui,sans-serif;background:#f7f9fb;color:#152534;margin:28px auto;max-width:1500px;padding:0 20px}h1{font-size:27px}p{line-height:1.55}.note{background:#fff2d8;border-left:4px solid #bc7b12;padding:14px}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}label{display:flex;flex-direction:column;gap:5px;font-size:12px}input,select,button{padding:9px;border:1px solid #c4cdd5;border-radius:5px;background:white;color:#152534}input[type=number]{width:90px}.cards{display:flex;gap:15px;flex-wrap:wrap;margin:18px 0}.card{padding:15px;background:white;min-width:160px;border:1px solid #dce4e9;border-radius:8px}.value{font-size:25px;font-weight:650}table{border-collapse:collapse;width:100%;background:white}th,td{padding:10px;text-align:left;border-bottom:1px solid #e1e8ec}th{position:sticky;top:0;background:#e8eff4}td:first-child{color:#637483}td:nth-child(2){font-family:ui-monospace,monospace;font-size:12px;max-width:550px;overflow-wrap:anywhere}.bar{height:7px;background:#e7edf0;width:130px;margin-top:4px}.fill{height:7px;background:#217c89}.small{color:#986700;font-size:11px}.links a{margin-right:17px}</style>
<h1>Historical case pass-rate ranking</h1><p>Snapshot: failure-review-export-20261029.zip. Results as recorded, not rescored. No November research runs are added.</p>
<p class="note">Rates use admissible saved run/score evidence after conservative exact-copy folding. Contamination, execution errors, missing score evidence and model stubs are excluded from the behavioral denominator. Pooled rates mix model/effort/prompt conditions and versions; they are not controlled estimates of intrinsic difficulty or independent observations.</p>
<p class="links"><a href="REPORT.md">Method and findings</a><a href="case_ranking.csv">Complete case CSV</a><a href="case_model_condition.csv">Model/condition strata</a><a href="case_ranking_raw_receipts.csv">Raw-copy sensitivity</a><a href="excluded_records.csv">Excluded records</a></p>
<div class="controls"><label>Model<select id="model"></select></label><label>Effort<select id="effort"></select></label><label>Condition<select id="condition"></select></label><label>Variant<select id="variant"></select></label><label>Case contains<input id="search" placeholder="case ID"></label><label>Minimum valid scores<input type="number" min="0" value="0" id="minn"></label><label>Order<select id="sort"><option value="hard">Lowest pass rate first</option><option value="easy">Highest pass rate first</option><option value="n">Largest sample first</option></select></label><button id="download">Download filtered CSV</button></div>
<div class="cards" id="cards"></div><p id="caption"></p><table><thead><tr><th>Rate rank</th><th>Case</th><th>Pass / valid</th><th>Pass rate</th><th>Excluded / unverified</th><th>Raw receipts</th><th>Config strata</th></tr></thead><tbody id="body"></tbody></table>
<script id="dataset" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('dataset').textContent);let shown=[];
for(const key of ['model','effort','condition','variant']){const s=document.getElementById(key);let o=document.createElement('option');o.value='';o.textContent='All';s.appendChild(o);for(const v of [...new Set(data.map(r=>r[key]))].sort()){o=document.createElement('option');o.value=v;o.textContent=v;s.appendChild(o)}}
function render(){const filters=Object.fromEntries(['model','effort','condition','variant'].map(k=>[k,document.getElementById(k).value])),q=document.getElementById('search').value.toLowerCase(),min=Number(document.getElementById('minn').value)||0,order=document.getElementById('sort').value,m=new Map();
for(const r of data){if(Object.entries(filters).some(([k,v])=>v&&r[k]!==v)||!r.case_id.toLowerCase().includes(q))continue;if(!m.has(r.case_id))m.set(r.case_id,{case_id:r.case_id,n:0,p:0,excluded:0,raw:0,strata:new Set()});const a=m.get(r.case_id);a.raw+=r.raw_copies;if(r.valid_score){a.n++;if(r.verdict==='PASS')a.p++;a.strata.add(JSON.stringify([r.model,r.effort,r.condition,r.variant,r.workflow_profile,r.timeout_seconds]))}else a.excluded++}
shown=[...m.values()].filter(r=>r.n>=min);shown.forEach(r=>r.rate=r.n?r.p/r.n:null);shown.sort((a,b)=>{if(a.rate===null||b.rate===null)return (a.rate===null)-(b.rate===null)||a.case_id.localeCompare(b.case_id);return (order==='n'?b.n-a.n:order==='easy'?b.rate-a.rate:a.rate-b.rate)||b.n-a.n||a.case_id.localeCompare(b.case_id)});
const total=shown.reduce((a,r)=>({n:a.n+r.n,p:a.p+r.p,excluded:a.excluded+r.excluded,raw:a.raw+r.raw}),{n:0,p:0,excluded:0,raw:0}),cards=document.getElementById('cards');cards.replaceChildren();for(const [label,val]of [['Cases shown',shown.length],['Pass / valid',total.p+' / '+total.n],['Pooled pass rate',total.n?(100*total.p/total.n).toFixed(2)+'%':'N/A'],['Excluded groups',total.excluded]]){const d=document.createElement('div');d.className='card';const v=document.createElement('div');v.className='value';v.textContent=val;d.appendChild(v);d.appendChild(document.createTextNode(label));cards.appendChild(d)}
document.getElementById('caption').textContent='Equal rates share a rank. Zero valid scores means N/A, not 0%. Samples below 10 are marked. Filters change the included population; rates are descriptive.';
const body=document.getElementById('body');body.replaceChildren();const rates=[...new Set(shown.filter(r=>r.rate!==null).map(r=>r.rate))].sort((a,b)=>order==='easy'?b-a:a-b);for(const r of shown){const tr=document.createElement('tr');for(const v of [r.rate===null?'—':rates.indexOf(r.rate)+1,r.case_id,r.p+' / '+r.n,r.rate===null?'N/A':(100*r.rate).toFixed(2)+'%',r.excluded,r.raw,r.strata.size]){const td=document.createElement('td');td.textContent=v;tr.appendChild(td)}if(r.rate!==null){const bar=document.createElement('div');bar.className='bar';const fill=document.createElement('div');fill.className='fill';fill.style.width=(100*r.rate)+'%';bar.appendChild(fill);tr.children[3].appendChild(bar)}if(r.n>0&&r.n<10){const note=document.createElement('div');note.className='small';note.textContent='small sample';tr.children[2].appendChild(note)}body.appendChild(tr)}}
for(const id of ['model','effort','condition','variant','minn','sort'])document.getElementById(id).addEventListener('change',render);document.getElementById('search').addEventListener('input',render);
document.getElementById('download').onclick=()=>{const esc=x=>'"'+String(x).replaceAll('"','""')+'"',rows=[['case_id','passes','valid_scores','pass_rate','excluded_groups','raw_receipts'],...shown.map(r=>[r.case_id,r.p,r.n,r.rate===null?'':r.rate,r.excluded,r.raw])],blob=new Blob(['\ufeff'+rows.map(r=>r.map(esc).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='filtered-case-ranking.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};render();</script></html>'''
 # Literal JS escape needs preservation inside the generated HTML.
 webpage=webpage.replace("join('\n')","join('\\n')")
 (A/'ranking.html').write_text(webpage.replace('__DATA__',payload))
 main=s['primary_copy_folded'];rawsum=s['raw_real_model_receipts'];dist=s['case_rate_distribution'];eligible=[r for r in rank if r['valid_scores']>=10]
 report=['Historical case pass-rate analysis','',f"Source: `{s['source_archive']}`. Complete discovery ledger: {s['inventory']['inventory_entries']:,} entries; {s['model_run_receipts_including_stubs']:,} model-bearing receipts including two explicitly named stubs. This is the October 29 export, not the November experience experiments.",'','The failure index alone is not a valid denominator: index.csv excludes PASS. The complete discovery-inventory.json was streamed from the ZIP without extracting 3.65 GB of archive material or executing any archived script. Its 11,886 run receipts and 7,565 PASS labels reconcile with the exporter summary.','',f"Primary descriptive result: {main['passes']:,}/{main['valid_scores']:,} = {pct(main['pass_rate'])}. The denominator includes only matched, mutually consistent saved run/score receipts with clear final status and no contamination or other explicit final validity failure. There are {main['behavioral_failures']:,} admitted behavioral failures and {main['excluded_or_unverified']:,} excluded/unverified real-model execution groups. No score has been rerun or independently re-certified.",'',f"Cases: {s['case_count']}; {s['cases_with_valid_scores']} have valid-score evidence. {dist['hundred_percent']} have observed 100%, {dist['zero_percent']} observed 0%, and {dist['between_zero_and_hundred']} fall between. All three zero-rate cases have only two valid scores. Six cases have fewer than ten valid scores. One case has no valid-score denominator.",'',f"Case-balanced mean rate (each of the 248 scored case IDs has equal weight): {pct(s['case_balanced_mean_pass_rate'])}; median case rate: {pct(s['median_case_pass_rate'])}. These are descriptive distributions, not estimates over independently sampled cases. {s['cases_with_multiple_recorded_manifest_or_input_hashes']} case IDs have multiple recorded manifest/input hashes; {s['valid_scores_missing_version_hash']} valid groups lack these version fields.",'', 'Counting rules:','', '- Model-bearing run.json receipts define the observation inventory. Standalone scores, controls and posthoc rescoring do not create new model attempts. Two explicit stub identities are excluded.', '- Final status must be SCORED or COMPLETED, verdict recognized, explicit validity not false, no contamination finding, outer validity status clear, and a matching associated score must exist with no case/variant/verdict disagreement or a contradictory PASS/runtime-error label. Completed candidate runtime failures retain their original non-PASS verdict and are separately flagged. These are historical receipt admission rules, not independent validation of grader semantics.', '- Missing score evidence, errors, contamination and unscored outcomes are excluded from the behavioral denominator. A zero denominator is N/A, never 0%. Candidate export incompleteness is not silently converted into a behavioral failure.', f"- {s['exact_duplicate_groups']} exact full-receipt copy groups were identified using a recorded execution identity and identical canonical receipt content. {s['copies_folded']} redundant copies were folded; all original paths remain in duplicate_groups.csv and execution_groups.csv. Different model attempts/retries are retained. Modified copies may remain, so no independence claim is made.", '- Case IDs remain separate; language/framework variants are not collapsed into independent source incidents. Model, effort, condition, variant, workflow profile, time budget and available version hashes are exposed in strata files.', '- A case can occur under different source/evaluator versions or mixed prompt conditions. Pooled rank is observational, not intrinsic difficulty or a controlled comparison. Equal exact pass fractions share a dense rank; sample size only breaks display ties. No significance or IID confidence-interval claims are made.','', 'Raw-copy sensitivity:','',f"Before copy folding: {rawsum['passes']:,}/{rawsum['valid_scores']:,} = {pct(rawsum['pass_rate'])}, excluding {rawsum['excluded_or_unverified']:,} unverified/error real-model receipts. After exact-copy folding: {pct(main['pass_rate'])}; change {(main['pass_rate']-rawsum['pass_rate'])*100:+.2f} percentage points. Both tables are retained. In particular, {s['pass_receipts_marked_contaminated']} PASS labels with CONTAMINATED status are not counted as valid passes.",'', 'Lowest pass rates with at least ten valid scores:', '',table(s['hardest_at_least_10_valid']),'','Highest pass rates with at least ten valid scores:', '',table(s['easiest_at_least_10_valid']),'','Cases used in the recent research discussion, where present in this older export:', '',table(s['prior_research_cases']),'','These older pooled rates do not describe the recent AUTO+automatic-Contract protocol. For example, current preferred gpt-5.6-terra/low has sparse per-case observations in this archive. The whole archive mixes six models and latent, provided-Contract and Generic conditions. Use the filters or case_model_condition.csv before choosing a comparable case.','', 'Complete ranking (all case IDs; lowest pass rate first):','',table(rank),'', 'Downloads and audit trail:','', '- ranking.html: standalone sortable/filterable table with model, effort, condition, variant and minimum sample size controls, plus filtered CSV download.', '- case_ranking.csv and case-ranking.json: primary exact-copy-folded ranking.', '- case_ranking_raw_receipts.csv: raw-receipt ranking and per-case copy sensitivity.', '- case_model_condition.csv and case_model_condition_version.csv: configuration and available-version strata.', '- model_effort_condition.csv: configuration aggregates; condition_deltas_descriptive.csv: within-recorded-stratum latent-baseline differences, descriptive only; absent baseline means no fabricated delta.', '- execution_groups.csv/json, duplicate_groups.csv and excluded_records.csv: every included/excluded group and all original source paths.', '- raw-run-receipts.jsonl and run-receipts.json: full original inventory run objects and reduced metadata; score/outer projections are kept separately.', '- inventory-audit.json, export-summary.json, source-provenance.json, offline-tests.log, integrity.json and ARTIFACTS.sha256: reconciliation, source identity and analysis integrity.','', 'Candidate runtime-error sensitivity:', '',f"Six completed behavioral-failure groups contain candidate runtime errors: source syntax errors, invalid decode arguments, or DEBUG output breaking the host protocol. Their original failures remain in the main denominator. Excluding all runtime-labelled groups as a sensitivity gives {s['runtime_exclusion_sensitivity']['passes']:,}/{s['runtime_exclusion_sensitivity']['valid_scores']:,} = {pct(s['runtime_exclusion_sensitivity']['pass_rate'])}. This does not relabel explicit CANDIDATE_RUNTIME_ERROR/SCORER_ERROR final statuses as completed scores. Evidence is in runtime-result-review.json.",'', 'Findings and implications:','', '1. Query-paused variants repeatedly appear among the lowest pooled pass rates. This supports considering them as historical difficulty signals, subject to matched model/condition and existing exposure; it does not prove a mechanism-specific cause.', '2. The new direct-routing cached-feed case and draft-autosave order example have high historical pooled rates, consistent with ceiling risk. Their sparse matched Terra/low evidence does not establish that every future attempt must pass.', '3. More than one thousand execution groups are unverified or invalid. Counting these as behavioral failures, or using the failure-only CSV as the complete dataset, would distort ranking.', '4. Use configuration-specific historical rows to shortlist candidates, fix a protocol before any new run, and record outcome-informed selection. No new experiment, model call, grading run, production update or Git commit is performed here.']
 (A/'REPORT.md').write_text('\n'.join(report)+'\n')
 save={'status':'COMPLETE_OFFLINE_ANALYSIS','model_calls':0,'scoring_calls':0,'tests_passed':11,'report':'REPORT.md','interactive_ranking':'ranking.html'};(A/'completion.json').write_text(json.dumps(save,indent=2)+'\n')
 print('Built complete report and interactive ranking',len(rank),'cases; embedded',len(data),'execution groups')

if __name__=='__main__':main()
